INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein ERP-System nur für große Unternehmen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs nutzen ERP"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle Größen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt ein ERP-System?', 3, '[{"text": "Integration von Geschäftsprozessen", "correct": true, "because": "Effizienz steigern"}, {"text": "Nur Daten speichern", "correct": false, "because": "Breitere Funktion"}, {"text": "Netzwerksicherheit erhöhen", "correct": false, "because": "Anderes Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Module gehören typischerweise zu einem ERP-System?', 5, '[{"text": "Finanzwesen", "correct": true, "because": "Buchhaltung"}, {"text": "Personalwesen", "correct": true, "because": "HR-Management"}, {"text": "Papierverarbeitung", "correct": false, "because": "Nicht ERP-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ERP-Systeme verbinden Unternehmensbereiche. b) Sie sind nur für Produktion.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Bereiche"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem ERP-System?', 4, '[{"text": "Datenintegration", "correct": false, "because": "Kernfunktion"}, {"text": "Prozessoptimierung", "correct": false, "because": "Hauptziel"}, {"text": "Papierdesign", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ERP-Systeme immer Cloud-basiert sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch On-Premise"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches ERP-System ist weit verbreitet?', 3, '[{"text": "SAP", "correct": true, "because": "Marktführer"}, {"text": "Apache", "correct": false, "because": "Webserver"}, {"text": "MySQL", "correct": false, "because": "Datenbank"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein ERP-System?', 5, '[{"text": "Zentralisierte Daten", "correct": true, "because": "Einheitliche Basis"}, {"text": "Prozesseffizienz", "correct": true, "because": "Automatisierung"}, {"text": "Papierproduktion", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ERP-Systeme integrieren Geschäftsprozesse. b) Sie sind nur für IT-Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Branchen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein ERP-System?', 4, '[{"text": "Datenbank", "correct": false, "because": "Daten speichern"}, {"text": "Integration", "correct": false, "because": "Prozesse verbinden"}, {"text": "Papierarchiv", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein ERP-System nur für große Datenmengen?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar"}, {"text": "Ja", "correct": false, "because": "Auch kleine Firmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse werden durch ERP-Systeme optimiert?', 4, '[{"text": "Lagerhaltung", "correct": true, "because": "Bestandsmanagement"}, {"text": "Buchhaltung", "correct": true, "because": "Finanzdaten"}, {"text": "Papierverarbeitung", "correct": false, "because": "Nicht ERP"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ERP-Systeme keine Updates benötigen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Regelmäßige Updates"}, {"text": "Ja", "correct": false, "because": "Wartung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem ERP-System?', 3, '[{"text": "Datenintegration", "correct": true, "because": "Zentralisierung"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ERP-Systeme verbessern Effizienz. b) Sie sind nur für Buchhaltung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele Bereiche"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei ERP-Systemen?', 5, '[{"text": "Implementierungskosten", "correct": true, "because": "Hoher Aufwand"}, {"text": "Komplexität", "correct": true, "because": "Schulung nötig"}, {"text": "Papierproduktion", "correct": false, "because": "Kein ERP-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem ERP-System unwichtig?', 3, '[{"text": "Datenintegration", "correct": false, "because": "Kernmerkmal"}, {"text": "Prozessautomatisierung", "correct": false, "because": "Effizienz"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein ERP-System Cloud-basiert sein?', 3, '[{"text": "Ja", "correct": true, "because": "Z. B. SAP S/4HANA Cloud"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ERP-Systeme nur für Produktion sind?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Branchen"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für ein ERP-System zentral?', 4, '[{"text": "Prozessintegration", "correct": true, "because": "Kernprinzip"}, {"text": "Papierdokumentation", "correct": false, "because": "Digital"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung"}]');
